const upsertTeamSleepDefault = `-- name: UpsertTeamSleepDefault :one
INSERT INTO team_sleep_defaults (owner_id, enabled, after_minutes)
VALUES ($1, $2, $3)
ON CONFLICT (owner_id) DO UPDATE
SET enabled       = excluded.enabled,
    after_minutes = excluded.after_minutes,
    updated_at    = now()
RETURNING owner_id, enabled, after_minutes, updated_at
`

type UpsertTeamSleepDefaultParams struct {
	OwnerID      string
	Enabled      bool
	AfterMinutes int32
}

